// ===== Namya settings: edit the values in quotes, then save =====
const SETTINGS = {
  sheetUrl: 'PASTE_SHEET_SCRIPT_URL_HERE', // Apps Script web app URL (ends in /exec)
  sheetKey: 'PASTE_NAMYA_KEY_HERE',        // same text as NAMYA_KEY in the sheet script
  sunilNumber: 'PASTE_SUNIL_NUMBER_HERE',  // e.g. 9779812345678 (977 + number, no + or spaces)
  wahaSession: '001',                      // session name shown in the WAHA dashboard
  testMode: true,                          // true: team messages also get drafts (for testing)
  team: ['Sunil', 'Sanket'],               // Blink staff names; no drafts for them when testMode is false
};
// ================================================================
return $input.all().map((item) => ({
  json: { ...SETTINGS, wahaUrl: 'http://waha:3000', body: item.json.body || item.json },
}));

// Keep only WhatsApp group messages from WAHA and reshape them for Namya.
// Everything else (private chats, status, other events) is dropped.
const out = [];
for (const item of $input.all()) {
  const { body, ...settings } = item.json;
  const b = body || {};
  if (b.event !== 'message.any' && b.event !== 'message') continue;
  const p = b.payload || {};
  const chat = p.fromMe ? (p.to || '') : (p.from || '');
  if (!chat.endsWith('@g.us')) continue;
  const name = (p._data && p._data.notifyName) || '';
  out.push({
    json: {
      ...settings,
      time: p.timestamp || Math.floor(Date.now() / 1000),
      groupId: chat,
      sender: p.fromMe ? 'Namya' : (name || p.participant || p.author || ''),
      text: p.body || '',
      hasFile: !!p.hasMedia,
      fromMe: !!p.fromMe,
    },
  });
}
return out;

// Free rule check (no AI): does this message need the team's attention?
// danger = money, complaints, contracts: Sunil gets an alert, never a draft.
const ASK = /\?|\b(price|rate|cost|charge|quote|package|ready|done|when|deadline|date|time|schedule|shoot|video|edit|reel|post|file|send|link|drive|status|update|meeting|call|blink|namya|please|plz|help|kati|kahile|kaile|kun|kasari|milcha|mildaina|pathau|pathaunu|garnu|chahiyo|kya|kab|kitna|kaise|kripya|bhejo)\b/i;
const ASK_NP = /(कति|कहिले|कसरी|कुन|मूल्य|भिडियो|पठाउ|कृपया|कब|कितना|कैसे)/;
const DANGER = /\b(pay|paid|payment|refund|discount|advance|invoice|bill|money|paisa|rupees?|npr|rs|contract|agreement|legal|lawyer|complain|complaint|angry|worst|disappointed|unhappy|cancel|delay|late|wrong|problem|issue|gunaso|bhuktani|chhut|naramro)\b/i;
const DANGER_NP = /(पैसा|भुक्तानी|छुट|रकम|सम्झौता|गुनासो|नराम्रो|ढिला|रद्द|शिकायत)/;

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  if (m.fromMe) continue;
  const sender = String(m.sender || '').toLowerCase();
  const isTeam = (m.team || []).some((n) => n && sender.includes(String(n).toLowerCase()));
  if (isTeam && !m.testMode) continue;
  const text = String(m.text || '').trim();
  if (!text && !m.hasFile) continue;
  const danger = DANGER.test(text) || DANGER_NP.test(text);
  if (!(m.hasFile || danger || ASK.test(text) || ASK_NP.test(text))) continue;
  out.push({ json: { ...m, text, danger } });
}
return out;

// Build the Claude request from the new message plus the group's memory.
const SYSTEM = `You are Namya, the front-office assistant for Blink Media Tech, a media production and digital marketing agency in Biratnagar, Nepal (videography, promotional videos, social media management, digital marketing, school and college media).

You read one new message from a client WhatsApp group and decide what the Blink team should do. A human (Sunil) reviews everything you write before any client sees it.

Choose one action:
- "draft": you can answer safely using only the information given. Write the reply.
- "needs_human": the message involves money (payments, advances, invoices, discounts, refunds), a price for custom work or anything not in the price list, a complaint or an unhappy client, contracts or legal promises, physical tasks, or you are not sure. Do not draft. Say briefly why in "reason".
- "no_reply": the message needs no answer (greetings, "ok", "thanks", emojis, team members talking to each other).

Rules for drafts:
- Reply in the same language and script the client used: Nepali (Devanagari), Romanised Nepali, Hindi or English.
- Sound like a friendly, professional Blink Media team member. WhatsApp style, 1 to 4 short sentences. No hashtags.
- Only quote prices that appear in the price list. Never invent prices, dates, deadlines, file links or promises. If the answer depends on facts you do not have, say the team will check and confirm soon.
- Use the group notes and recent messages to understand who the client is, what was promised and what is pending.
- Follow-up tone: firmer for clients in Nepal, India and the rest of Asia, Africa and North America; softer for Australia and Europe.

Answer with only a JSON object and nothing else:
{"action": "draft" or "needs_human" or "no_reply", "reason": "one short sentence for Sunil", "reply": "the draft reply, or empty"}`;

const originals = $('Needs reply?').all();
return $input.all().map((item, i) => {
  const m = originals[i].json;
  const mem = (item.json && item.json.ok) ? item.json : {};
  const prices = (mem.prices || []).map((p) => `- ${p.package}: ${p.includes} | NPR ${p.priceNpr}${p.notes ? ' | ' + p.notes : ''}`);
  const recent = (mem.recent || []).map((r) => `${r.sender}: ${r.text}`);
  const groupName = mem.groupName || 'Unknown group';
  const user = [
    `Group: ${groupName} | Project: ${mem.project || 'unknown'} | Region: ${mem.region || 'unknown'}`,
    `Group notes: ${mem.notes || '(none yet)'}`,
    `Price list:\n${prices.length ? prices.join('\n') : '(empty: do not quote any price)'}`,
    `Recent messages, oldest first:\n${recent.length ? recent.join('\n') : '(none)'}`,
    `New message from ${m.sender}: "${m.text}"${m.hasFile ? ' (the client also sent a file)' : ''}`,
    `Safety check found money, complaint or contract words: ${m.danger ? 'yes' : 'no'}`,
  ].join('\n\n');
  return {
    json: {
      ...m,
      groupName,
      request: {
        model: 'claude-haiku-5-5',
        max_tokens: 800,
        output_config: { effort: 'low' },
        system: [{ type: 'text', text: SYSTEM, cache_control: { type: 'ephemeral' } }],
        messages: [{ role: 'user', content: user }],
      },
    },
  };
});

// Turn Claude's answer into a private WhatsApp message for Sunil.
// Anything unclear, or any AI error, becomes a "Needs you" alert.
const originals = $('Build prompt').all();
const out = [];
$input.all().forEach((item, i) => {
  const m = originals[i].json;
  const num = String(m.sunilNumber || '').replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(num)) throw new Error('Set sunilNumber in the Settings box first');
  const resp = item.json || {};
  const text = Array.isArray(resp.content)
    ? resp.content.filter((b) => b.type === 'text').map((b) => b.text).join('')
    : '';
  let r = null;
  try { r = JSON.parse((text.match(/\{[\s\S]*\}/) || [''])[0]); } catch (e) { r = null; }
  if (!r || resp.stop_reason === 'refusal' || !['draft', 'needs_human', 'no_reply'].includes(r.action)) {
    r = { action: 'needs_human', reason: 'Namya could not draft this one (AI error), please check.', reply: '' };
  }
  if (m.danger && r.action !== 'needs_human') {
    r = { action: 'needs_human', reason: r.reason || 'Money, complaint or contract topic.', reply: '' };
  }
  if (r.action === 'draft' && !String(r.reply || '').trim()) {
    r = { action: 'needs_human', reason: 'Namya had no safe reply.', reply: '' };
  }
  if (r.action === 'no_reply') return;
  const said = String(m.text || '(file)').slice(0, 500);
  const head = `*${m.groupName}*\nFrom ${m.sender}: "${said}"`;
  const message = r.action === 'draft'
    ? `📝 Draft reply for ${head}\n\nSuggested reply:\n${r.reply}\n\n(Copy it into the group if it is OK, or edit it first.)`
    : `⚠️ Needs you: ${head}\n\nWhy: ${r.reason}\n\nNamya has not drafted a reply.`;
  out.push({ json: { wahaUrl: m.wahaUrl, session: m.wahaSession, chatId: `${num}@c.us`, message } });
});
return out;
